CREATE TABLE users(id SERIAL PRIMARY KEY, name TEXT, pw TEXT NOT NULL, role TEXT DEFAULT 'user', token_ver INT NOT NULL DEFAULT 0, failed INT NOT NULL DEFAULT 0, locked_until TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE user_idents(ident TEXT PRIMARY KEY, user_id INT NOT NULL REFERENCES users ON DELETE CASCADE, kind TEXT NOT NULL, created TIMESTAMPTZ DEFAULT now());
CREATE TABLE otps(ident TEXT NOT NULL, purpose TEXT NOT NULL, code TEXT, exp TIMESTAMPTZ, attempts INT DEFAULT 0, created TIMESTAMPTZ DEFAULT now(), PRIMARY KEY(ident,purpose));
CREATE TABLE teams(id SERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL, logo TEXT, years TEXT DEFAULT '', captain TEXT DEFAULT '', coach TEXT DEFAULT '', owner TEXT DEFAULT '', venue TEXT DEFAULT '', website TEXT DEFAULT '', facebook TEXT DEFAULT '', instagram TEXT DEFAULT '', x TEXT DEFAULT '');
CREATE SEQUENCE player_code_seq;
CREATE TABLE players(id SERIAL PRIMARY KEY, code TEXT NOT NULL UNIQUE DEFAULT 'UKP'||lpad(nextval('player_code_seq')::text,4,'0'), name TEXT NOT NULL, team_id INT REFERENCES teams ON DELETE CASCADE, role TEXT, photo_url TEXT, dob TEXT, bat_style TEXT, bowl_style TEXT, playing_role TEXT, career TEXT);
CREATE TABLE season_stats(id SERIAL PRIMARY KEY, player_id INT REFERENCES players ON DELETE CASCADE, team_id INT NOT NULL REFERENCES teams ON DELETE CASCADE, format TEXT, year INT, matches INT DEFAULT 0, runs INT DEFAULT 0, wickets INT DEFAULT 0, hs INT DEFAULT 0, innings INT DEFAULT 0, fifties INT DEFAULT 0, hundreds INT DEFAULT 0, double_hundreds INT DEFAULT 0, triple_hundreds INT DEFAULT 0, not_outs INT DEFAULT 0, sixes INT DEFAULT 0, fours INT DEFAULT 0, sr NUMERIC DEFAULT 0, bowl_inn INT DEFAULT 0, best TEXT DEFAULT '-', w3 INT DEFAULT 0, w5 INT DEFAULT 0, econ NUMERIC DEFAULT 0, bowl_avg NUMERIC DEFAULT 0, catches INT DEFAULT 0, runouts INT DEFAULT 0, stumpings INT DEFAULT 0, UNIQUE(player_id,format,year,team_id));
CREATE TABLE news(id SERIAL PRIMARY KEY, title TEXT NOT NULL, tag TEXT DEFAULT 'News', img TEXT, body TEXT, created_at TIMESTAMPTZ DEFAULT now());
